class Solution {
    unordered_map<int, bool> memo;
    bool dfs(int mask, int total, int maxInt, int desired) {
        if (memo.count(mask)) return memo[mask];
        for (int i = 1; i <= maxInt; ++i) {
            int bit = 1 << (i - 1);
            if (!(mask & bit)) {
                if (total + i >= desired || !dfs(mask | bit, total + i, maxInt, desired)) {
                    return memo[mask] = true;
                }
            }
        }
        return memo[mask] = false;
    }
