class Solution {
    private Map<Integer, Boolean> memo = new HashMap<>();
    public boolean canIWin(int maxChoosableInteger, int desiredTotal) {
        if (desiredTotal <= 0) return true;
        int sum = maxChoosableInteger * (maxChoosableInteger + 1) / 2;
        if (sum < desiredTotal) return false;
        return dfs(0, 0, maxChoosableInteger, desiredTotal);
    }
    private boolean dfs(int mask, int total, int maxInt, int desired) {
        if (memo.containsKey(mask)) return memo.get(mask);
        for (int i = 1; i <= maxInt; ++i) {
            int bit = 1 << (i - 1);
            if ((mask & bit) == 0) {
                if (total + i >= desired || !dfs(mask | bit, total + i, maxInt, desired)) {
                    memo.put(mask, true);
                    return true;
                }
            }
        }
        memo.put(mask, false);
        return false;
    }
}

var canIWin = function(maxChoosableInteger, desiredTotal) {
    if (desiredTotal <= 0) return true;
    const sum = (maxChoosableInteger * (maxChoosableInteger + 1)) / 2;
    if (sum < desiredTotal) return false;
    const memo = new Map();
    function dfs(mask, total) {
        if (memo.has(mask)) return memo.get(mask);
        for (let i = 1; i <= maxChoosableInteger; ++i) {
            const bit = 1 << (i - 1);
            if (!(mask & bit)) {
                if (total + i >= desiredTotal || !dfs(mask | bit, total + i)) {
                    memo.set(mask, true);
                    return true;
                }
            }
        }
        memo.set(mask, false);
        return false;
    }
    return dfs(0, 0);
};
